 {#if loadingPassage}<p role="status">{ui.loadingBody}</p>{/if}
 {#if learned}<section class="learned"><svg class="learned-check" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 25l9 9L39 14"/></svg><h1>{review?ui.reviewed:ui.learned}</h1><article class="keepsake" style:background={collectionColor(practice)}><p>{practice.text}</p><EsvAttribution translation={practice.translation}/><footer><b>{practice.title}</b><small>{sourceLabel(practice)}</small></footer></article>{#if nextDue}<small>{ui.nextReviewPrefix}{nextDue}</small>{/if}<Button onclick={loadNext}>{session.length?ui.nextItem:ui.backToToday}</Button><Button secondary onclick={()=>{learned=false;rehearsal=true;review=false;restart()}}>{ui.practiceOnceMore}</Button></section>
 {:else}<section class="practice" bind:this={practiceRegion} tabindex="-1" aria-label={ui.practiceRegionLabel} inert={result} aria-hidden={result}><header><button class="icon" aria-label={ui.closePractice} onclick={()=>practice=null}>×</button><StepDots step={attemptStep}/>{#if attemptStep===1&&!review}<Button secondary onclick={know}>{ui.knowThis}</Button>{:else}<button class="icon" aria-label={ui.restartStep} onclick={restart}>↻</button>{/if}</header><div class="prompt" class:collapsed={position>0&&!titleExpanded}><small>{review?ui.reviewBlankRecall:ui.stepPrefix+attemptStep+ui.stepOfFour+[ui.empty,ui.readAlong,ui.fewWordsHidden,ui.almostFromMemory,ui.fromMemory][attemptStep]}</small><h1><button class="prompt-title" aria-expanded={titleExpanded||position===0} onclick={()=>titleExpanded=!titleExpanded}>{practice.title}</button></h1><small>{sourceLabel(practice)}</small></div><div class="progress"><i style:width={position/words.length*100+ui.percent}></i></div><VerseText {words} {mask} text={practice.text} index={position} slipped={visualSlips}/><EsvAttribution translation={practice.translation}/>{#key practice.id}<Keyboard hasNumbers={words.some(word=>/^\d/.test(word))} onkey={key} onpeek={()=>key(ui.empty,true)} disabled={result||completing}/>{/key}</section>{/if}
 {#if result}<Sheet title={resultTitle} close={()=>{result=false;practice=null}}><p>{resultDetail}</p><Button onclick={continueResult}>{review&&!resultLearned?ui.relearnNow:rehearsal?ui.done:resultLearned?ui.finish:ui.continue}</Button><Button secondary onclick={()=>{practice=null;result=false}}>{review&&!resultLearned?ui.later:ui.closePractice}</Button></Sheet>{/if}
{:else}
 <section class="page" class:has-toast={showAddedToast||!!undoItem} class:account={tab===ui.account}>
 <header class:collection-header={!!detail}>{#if !detail}<div><h1>{tab===ui.account?ui.accountTitle:tab===ui.gallery?ui.components:tab}</h1>{#if tab===ui.today}<p>{new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"})}</p>{/if}</div>{/if}<button class="icon" aria-label={detail?ui.backToLibrary:ui.accountSettings} onclick={()=>detail?openCollection(''):navigate(ui.account)}>{#if detail}{ui.backGlyph}{:else if data.settings.name.trim()}{data.settings.name.trim().slice(0,1).toUpperCase()}{:else}<svg class="person" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>{/if}</button></header>
 {#if loadingPassage}<p role="status">{ui.loadingBody}</p>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if tab===ui.today}
 <div class="rhythm"><div><b>{weekCount}{ui.of}{data.settings.goal}{ui.thisWeekSuffix}</b></div><WeekDots days={data.settings.days}/></div>
 {#if due.length}<div class="hero"><div><b>{practiceCount(due.length)}</b><small>{minutes(estimatedMinutes)}</small></div><Button onclick={()=>begin(due)}>{ui.begin}</Button></div><h3 class="section-title">{ui.forToday}</h3><List>{#each due as item}<Row title={item.title} subtitle={`${item.learned?ui.review:item.step===1?ui.new:ui.learningStep(item.step)} · ${sourceLabel(item)}`} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row>{/each}</List>
 {:else}<div class="empty"><div class="heart">♡</div><h2>{live.length?ui.doneForToday:ui.noItemsYet}</h2>{#if !live.length}<p>{ui.addCollection}</p>{/if}<Button onclick={()=>navigate(ui.library)}>{live.length?ui.visitLibrary:ui.browseLibrary}</Button></div>{/if}
 {:else if tab===ui.library}
 {#if detail}<Cover title={collectionTitle(detail)} subtitle={plural(detailItems.length,"item")} color={starters.findIndex((s:any)=>s.id===detail)} compact/><div class="section-title"><h3>{ui.yourItems}</h3><button class="text-button" onclick={()=>{const target=detail;navigate(ui.discover);addTarget=target}}>{ui.addItems}</button></div><List>{#each detailItems as item}<Row title={item.title} subtitle={item.learned?ui.reviewDate(item.due):ui.stepPrefix+item.step} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/>{#snippet trailing()}<button class="text-button item-menu" aria-label={ui.optionsPrefix+item.title} onclick={()=>removeTarget=item}>…</button>{/snippet}</Row>{#if !item.learned&&!due.some(i=>i.id===item.id)}<button class="text-button" onclick={()=>begin([item])}>{ui.startEarly}</button>{/if}{/each}</List>{#if detailItems.length}<div class="collection-practice"><Button onclick={()=>begin(detailItems)}>{ui.startPractice}</Button></div>{:else}<p>{ui.nothingHere}</p>{/if}
 {:else}<h3 class="section-title">{ui.startHere}</h3><div class="covers">{#each starters as s,i}<Cover title={s.title} subtitle={(live.some(item=>item.collection===s.id)?ui.learnedCheck:'')+s.subtitle} color={i} onclick={()=>live.some(item=>item.collection===s.id)?openCollection(s.id):preview=s}/>{/each}</div><div class="section-title"><h3>{ui.yours}</h3><button class="text-button" onclick={()=>navigate(ui.discover)}>{ui.addShortcut}</button></div><List>{#each [...new Set(live.map(i=>i.collection))] as id}{@const items=live.filter(i=>i.collection===id)}<Row title={collectionTitle(id)} subtitle={items.filter(i=>i.learned).length+ui.of+items.length+ui.learnedSuffix} onclick={()=>openCollection(id)}><ProgressPie percent={items.filter(i=>i.learned).length/items.length*100}/></Row>{/each}</List>{#if !live.length}<p>{ui.libraryEmpty}</p>{/if}{/if}
 {:else if tab===ui.discover}
 <div class="stack"><div class="segments" aria-label={ui.contentType}>{#each [[ui.verseMode,ui.verses],[ui.ownMode,ui.yourText],[ui.documentsMode,ui.catechisms]] as [id,label]}<button class="segment" class:active={addMode===id} aria-pressed={addMode===id} onclick={()=>{addMode=id;found=[]}}>{label}</button>{/each}</div>
 {#if addMode===ui.verseMode}<label>{ui.translation}<select bind:value={translation}><option>{ui.bsb}</option><option>{ui.kjv}</option><option>{ui.web}</option><option>{incord.esv}</option></select></label><label>{ui.bibleReference}<input bind:value={reference} placeholder={ui.referencePlaceholder} onkeydown={e=>{if(e.key===ui.enterKey)void search()}}/></label><Button onclick={()=>void search()} disabled={busy}>{ui.findVerses}</Button>{#if found.length}<div class="passage-actions"><div class="segments passage-segments" aria-label={ui.passageMode}>{#each [['passage',ui.onePassage],['separate',ui.separateVerses],['chunks',ui.chunks]] as [mode,label]}<button class="segment" class:active={passageMode===mode} aria-pressed={passageMode===mode} onclick={()=>passageMode=mode}>{label}</button>{/each}</div><Button onclick={()=>void add(passageItems(),undefined,false,tokenize(found.map(i=>i.text).join(' ')).length>500)}>{ui.addToLibrary}</Button></div><List>{#each found as item}<Row title={item.title} subtitle={item.text}/><EsvAttribution translation={item.translation}/>{/each}</List>{/if}{#if translation===incord.esv}<EsvAttribution translation={incord.esv}/>{:else}<small>{ui.publicDomainNotice}</small>{/if}
 {:else if addMode===ui.ownMode}<label>{ui.titleOrQuestion}<input bind:value={customTitle} maxlength={200}/></label><label>{ui.textToRemember}<textarea bind:value={customText} maxlength={10000}></textarea></label><p>{ui.privateTextNotice}</p><Button onclick={()=>void own()}>{ui.addYourText}</Button>
 {:else}<label>{ui.browse}<select bind:value={selectedDoc}><option value="">{ui.chooseDocument}</option>{#each documents as doc}<option value={doc.id}>{doc.title}</option>{/each}</select></label>{#if selectedDoc}{@const doc=documents.find((d:any)=>d.id===selectedDoc)}{#if doc}<div class="bulk-actions">{#if doc.items.length>12}<Button secondary onclick={()=>void add(doc.items.slice(0,12),doc.id)}>{['apostles','nicene'].includes(doc.id)?ui.addFirstArticles:ui.addFirstQuestions}</Button><Button secondary onclick={()=>void add(doc.items.filter(i=>!live.some(x=>x.id===i.id)).slice(0,12),doc.id)}>{['apostles','nicene'].includes(doc.id)?ui.addNextArticles:ui.addNextQuestions}</Button>{/if}<Button secondary onclick={()=>{confirmBatch=doc.items;batchCollection=doc.id}}>{ui.addAll}</Button></div><List>{#each doc.items as item,i}{#if item.lordsDay&&(i===0||doc.items[i-1].lordsDay!==item.lordsDay)}<h3>{ui.lordsDay(item.lordsDay)}</h3>{/if}<div class="document-row"><details><summary>{['apostles','nicene'].includes(doc.id)?ui.articleTitle(item.number||i+1,item.text):(item.number?ui.questionPrefix(item.number):'')+item.title}</summary><p>{item.text}</p></details><button class="icon document-add" aria-label={live.some(x=>x.id===item.id)?ui.added:!['apostles','nicene'].includes(doc.id)&&item.number?ui.addQuestion(item.number):ui.addArticle} disabled={live.some(x=>x.id===item.id)} onclick={()=>void add([item],doc.id)}>{live.some(x=>x.id===item.id)?'✓':'+'}</button></div>{/each}</List>{/if}{/if}{/if}</div>
 {:else if tab===ui.account}
 <div class="stack"><section class="settings-group" aria-label={ui.preferences}><label>{ui.displayName}<input bind:value={data.settings.name} onchange={()=>void save()} maxlength={80}/></label><label>{ui.appearance}<select bind:value={data.settings.theme} onchange={(event)=>{data.settings.theme=event.currentTarget.value;stats.trackStats(`theme:${data.settings.theme}`);void save()}}><option value="system">{ui.system}</option><option value="light">{ui.light}</option><option value="dark">{ui.dark}</option></select></label><label>{ui.textSize}<select bind:value={data.settings.textSize} onchange={(event)=>{data.settings.textSize=event.currentTarget.value;stats.trackStats(`text_size:${data.settings.textSize}`);void save()}}>{#each ui.textSizes as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>{ui.weeklyRhythm}<select bind:value={data.settings.goal} onchange={()=>void save()}>{#each RULES.rhythmOptions as n}<option value={n}>{ui.weekOption(n)}</option>{/each}</select></label><label>{ui.reminderTime}<input type="time" bind:value={data.settings.reminderTime} onchange={()=>void save()}/></label><label>{ui.newPerDay}<select bind:value={(data.settings as any).newPerDay} onchange={()=>void save()}>{#each [1,2,3,5] as n}<option value={n}>{n}</option>{/each}</select></label><label>{ui.searchZones}<input type="search" placeholder={ui.searchZones} bind:value={zoneSearch}/></label><label>{ui.timeZone}<select bind:value={data.settings.timeZone} onchange={()=>void save()}>{#each zones.filter(z=>z===data.settings.timeZone||z.toLowerCase().includes(zoneSearch.toLowerCase())) as zone}<option>{zone}</option>{/each}</select></label>
 </section><section class="settings-group" aria-labelledby="account-heading"><h3 id="account-heading">{ui.yourAccount}</h3>{#if account}<p>{ui.signedIn}</p>{#if mergePrompt&&mergeDismissed}<Button secondary onclick={()=>mergeDismissed=false}>{ui.reviewDeviceItems}</Button>{/if}{#if !devicePasskey}<Button secondary onclick={()=>void signup()} disabled={busy}>{ui.addDevicePasskey}</Button>{/if}{#if !online}<small>{ui.offlineSync}</small>{/if}<Button secondary onclick={()=>confirmSignout=true}>{ui.signOut}</Button><Button secondary onclick={()=>confirmEverywhere=true}>{ui.signoutEverywhere}</Button>{:else}<p>{ui.localAccountNotice}</p><Button onclick={()=>void signup()} disabled={busy}>{ui.createPasskey}</Button><Button secondary onclick={()=>void signin()} disabled={busy}>{ui.signInPasskey}</Button><Button secondary onclick={()=>void signin(true)} disabled={busy}>{incord.legacySignin}</Button>{#if config.google}<Button secondary onclick={()=>location.href=ui.googleAuthPath}>{ui.continueGoogle}</Button>{/if}<label>{ui.recoveryCode}<input bind:value={recoverInput} autocomplete="off"/></label><Button secondary onclick={()=>void recover()} disabled={busy||!recoverInput}>{ui.useRecoveryCode}</Button>{/if}
 </section><section class="settings-group" aria-labelledby="reminder-heading"><h3 id="reminder-heading">{ui.reminders}</h3><p>{ui.reminderInstructions}</p><p>{pushState==='on'?ui.reminderOn:pushState==='missing'?ui.reminderMissing:pushState==='denied'?ui.reminderDenied:pushState==='unsupported'?ui.iosInstallNotice:pushState==='unavailable'?ui.deliveryUnavailable:ui.reminderOff}</p><Button secondary disabled={pushState==='denied'||pushState==='unsupported'} onclick={()=>void (pushState==='on'?disablePush():enablePush())}>{pushState==='on'?ui.disableReminders:pushState==='missing'?ui.turnOnAgain:ui.enableReminders}</Button>{#if pushState==='on'}<Button secondary onclick={()=>void testPush()}>{ui.sendTestPush}</Button>{/if}<details><summary>{ui.deliveryLog}</summary>{#if deliveries.length}<ul>{#each deliveries as delivery}<li><small>{delivery.time?new Date(delivery.time).toLocaleString():''} · {ui.pushProvider(delivery.host)}</small><p>{ui.pushOutcome(delivery.host,delivery.status,delivery.reason)}</p></li>{/each}</ul>{:else}<p>{ui.deliveryEmpty}</p>{/if}</details>
 </section><section class="settings-group" aria-labelledby="privacy-heading"><h3 id="privacy-heading">{incord.privacy}</h3><label><input type="checkbox" bind:checked={shareCounts} disabled={privacySignal} onchange={setShareCounts}/>{incord.shareCounts}</label><small>{incord.countsDetail}</small>{#if privacySignal}<small>{incord.privacySignal}</small>{/if}</section><section class="settings-group" aria-label={ui.dataLabel}><Button secondary onclick={()=>void exportData()}>{ui.exportData}</Button>{#if account}<Button secondary onclick={()=>confirmDelete=true}>{ui.deleteAccount}</Button>{/if}</section><section class="settings-group" aria-label={ui.aboutLabel}><h3>{ui.aboutVersion(appVersion)}</h3><small>{ui.aboutApp}</small><p>{incord.privacyAbout}</p><EsvAttribution translation={incord.esv}/></section></div>
 {:else if tab===ui.gallery}<div class="gallery"><Button>{ui.primaryButton}</Button><Button secondary>{ui.secondaryButton}</Button><StepDots step={3}/><WeekDots days={data.settings.days}/><Cover title={ui.gospelTitle} subtitle={ui.galleryVerseCount} color={0} large/><Row title={ui.johnReference} subtitle={ui.galleryStep}><StepDots step={2}/></Row><VerseText words={[ui.sampleFor,ui.sampleGod,ui.sampleSo,ui.sampleLoved,ui.sampleThe,ui.sampleWorld]} mask={[false,true,false,true,true,false]} index={2}/><Keyboard onkey={()=>{}} onpeek={()=>{}}/></div>{/if}
 </section><TabBar active={tab} onchange={navigate}/>
{/if}
{#if recovery}<Sheet title={ui.recoveryTitle} close={()=>recovery=ui.empty}><p>{ui.recoveryInstructions}</p><code data-testid="recovery-code">{recovery}</code><Button onclick={()=>recovery=ui.empty}>{ui.recoverySaved}</Button></Sheet>{/if}
{#if confirmDelete}<Sheet title={ui.deleteTitle} close={()=>confirmDelete=false}><p>{ui.deleteInstructions}</p><Button onclick={()=>void deleteAccount()}>{ui.confirmDelete}</Button><Button secondary onclick={()=>confirmDelete=false}>{ui.keepAccount}</Button></Sheet>{/if}
{#if welcome}<Sheet title={ui.welcomeBack} close={()=>welcome=false}><p>{ui.welcomeCount(Math.min(3,live.filter(i=>i.learned).length))}</p><Button onclick={()=>{data.settings.returnStart=today();welcome=false;void save()}}>{ui.start}</Button><Button secondary onclick={()=>{data.settings.returnStart=today();welcome=false;void save();begin(live.filter(i=>i.learned).slice(0,3))}}>{ui.checkMemory}</Button></Sheet>{/if}
{#if preview}<Sheet title={preview.title} close={()=>preview=null}><List>{#each preview.items as item}<Row title={item.title} subtitle={item.text}/><EsvAttribution translation={item.translation}/>{/each}</List><Button onclick={()=>void addStarter(preview)}>{ui.addToMyLibrary}</Button></Sheet>{/if}
{#if removeTarget}<Sheet title={ui.removeTitle} close={()=>removeTarget=null}><p>{ui.removeDetail(removeTarget.title)}</p><Button onclick={()=>void remove(removeTarget!)}>{ui.remove}</Button><Button secondary onclick={()=>removeTarget=null}>{ui.keepItem}</Button></Sheet>{/if}
{#if showAddedToast}<div class="added-toast" role="status">{addedToast}</div>{/if}
{#if undoItem&&!practice}<div class="undo-toast" role="status">{ui.removed} <button class="text-button" onclick={()=>void undo()}>{ui.undo}</button></div>{/if}
{#if confirmBatch}<Sheet title={ui.batchTitle(confirmBatch.length)} close={()=>confirmBatch=null}><Button onclick={()=>{const items=confirmBatch!;confirmBatch=null;void add(items,batchCollection,true)}}>{ui.addItems}</Button><Button secondary onclick={()=>confirmBatch=null}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmSignout}<Sheet title={ui.signoutTitle} close={()=>confirmSignout=false}><p>{ui.signoutDetail}</p><Button onclick={()=>{confirmSignout=false;void signout()}}>{ui.signOut}</Button><Button secondary onclick={()=>confirmSignout=false}>{ui.cancel}</Button></Sheet>{/if}
{#if mergePrompt&&!mergeDismissed&&!recovery&&!discardPrompt}<Sheet title={ui.mergeTitle(live.length)} close={()=>mergeDismissed=true}><p>{ui.mergeHistoryDetail}</p><Button onclick={()=>void acceptMerge()}>{ui.mergeAdd}</Button><Button secondary onclick={()=>discardPrompt=true}>{ui.keepSeparate}</Button></Sheet>{/if}
{#if discardPrompt}<Sheet title={ui.discardTitle} close={()=>discardPrompt=false}><p>{ui.discardDetail}</p><Button onclick={()=>void discardLocal()}>{ui.discardLocal}</Button><Button secondary onclick={()=>discardPrompt=false}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmEverywhere}<Sheet title={ui.signoutEverywhereTitle} close={()=>confirmEverywhere=false}><p>{ui.signoutEverywhereDetail}</p><Button onclick={()=>{confirmEverywhere=false;void signout(true)}}>{ui.signoutEverywhere}</Button><Button secondary onclick={()=>confirmEverywhere=false}>{ui.cancel}</Button></Sheet>{/if}
{#if passkeyPrompt&&!recovery&&!(mergePrompt&&!mergeDismissed)&&!discardPrompt}<Sheet title={legacyPasskeyPrompt?incord.incordPasskey:ui.addDevicePasskey} close={()=>passkeyPrompt=false}><p>{legacyPasskeyPrompt?incord.incordPasskeyDetail:ui.recoveryPasskeyPrompt}</p><Button onclick={()=>void signup()}>{legacyPasskeyPrompt?incord.incordPasskey:ui.addDevicePasskey}</Button><Button secondary onclick={()=>passkeyPrompt=false}>{ui.later}</Button></Sheet>{/if}
</main>
